export function installGoldEvolutions(pools){for(const spec of GOLD_EVOLUTIONS){const card=pools[spec.owner].find(c=>c.key===spec.key);card.name=spec.name;card.evolved=true;card.describe=r=>spec.description+'。'+(![3,8].includes(spec.owner)?`仅附近交战时触发；${spec.owner===0?'穹周围 300':'自身周围 360，且目标距穹不超过 500'}内生效。`:'')+(spec.kind==='windBlades'?`每次 ${8+4*(r-1)} 道风刃，飞行 360 距离；冲锋中每 0.3 秒一轮，每道造成技能 ${50+15*r}%。`:spec.kind==='retire'?`自爆伤害范围内的 BOSS 承受技能 ${800+400*r}%；爆炸持续 ${1+r*.3} 秒。`:spec.kind==='souls'?`每魂移速 +${r*1.5}%、攻速 +${r*2}%，最多吸收 ${30+20*r} 魂；加速保留至离开当前地图或进入下一层。`:`每 ${spec.kind==='formation'?10:9} 秒触发一次，持续 ${3+r} 秒。`+(['coneRain','coneIce'].includes(spec.kind)?`每 0.6 秒一轮 ${7+r*2} 枚；冻结 ${(.6+.3*r).toFixed(1)} 秒。`:['toxinBarrage','medicBarrage'].includes(spec.kind)?`每 0.6 秒向最多 ${2+r} 名敌人发射子弹。${spec.kind==='toxinBarrage'?`中毒持续 3 秒，每秒 ${8*r} 伤害。`:`每次命中恢复 ${3+r} 点生命。`}`:['rain','eruption','blizzard'].includes(spec.kind)?`每 0.6 秒最多 ${2+r} 个落点，落点半径 ${Math.round(Math.min(180+45*r,[3,8].includes(spec.owner)?999:270)*.55)}。`:spec.kind==='formation'?`全队每处攻击半径 ${Math.round(Math.min(180+45*r,[3,8].includes(spec.owner)?999:270)*.7)}。`:['web','beams','dragon'].includes(spec.kind)?'范围内每 0.6 秒结算一次攻击。':`最大覆盖半径 ${spec.owner===1&&spec.key==='iceShield'?150+15*r:Math.min(180+45*r,[3,8].includes(spec.owner)?999:270)}，每 0.6 秒结算一次攻击。`));}}
